/* v1.4 Account, cloud saves and shared board battle */
#bpAccountBtn{background:linear-gradient(#6dbeaa,#318d78)!important;box-shadow:0 4px 0 #24725e!important}
#bpSharedBtn,#bpSharedFromOnline{background:linear-gradient(#b18bf3,#7954c2)!important;box-shadow:0 4px 0 #60409d!important}
#bpAccountModal,#bpSharedModal{position:fixed;inset:0;z-index:5350;display:none;align-items:center;justify-content:center;padding:10px;background:rgba(10,24,52,.82);backdrop-filter:blur(5px)}
#bpAccountModal.show,#bpSharedModal.show{display:flex}
.bpScreen{width:min(96vw,510px);max-height:94dvh;overflow-y:auto;background:linear-gradient(160deg,#fff,#ecf5ff);border-radius:22px;box-shadow:0 18px 50px #08152b77;padding:15px;color:#28385d}
.bpHead{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:12px}.bpHead h2{margin:0;font-size:20px}
.bpText{font-size:12px;line-height:1.55;margin:7px 0;color:#4b6384}.bpHint{font-size:11px;color:#647b9b;line-height:1.5;margin-top:7px}
.bpForm{display:grid;gap:8px}.bpForm label{display:grid;gap:3px;font-size:12px;font-weight:900}.bpForm input,.bpInput{width:100%;min-width:0;border:1px solid #b8cdec;border-radius:10px;padding:10px;font-size:14px;background:#fff;color:#223854}
.bpRow{display:flex;gap:7px;flex-wrap:wrap;align-items:center}.bpRow button{flex:1;min-width:102px}.bpRow input{flex:1}
.bpStatus{padding:9px;margin:8px 0;border-radius:10px;min-height:35px;background:#e0eeff;color:#23528f;font-size:12px;font-weight:850;white-space:pre-wrap}
.bpAccountCard{padding:12px;background:#e5f6f5;border-radius:12px;margin-top:8px}.bpAccountCard button{margin-top:6px}
#bpSharedBoard{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:3px;width:min(86vw,340px);height:min(86vw,340px);aspect-ratio:1;margin:10px auto;background:#9aadd8;padding:5px;border-radius:14px}
.bpSharedCell{min-width:0;min-height:0;padding:0;border-radius:5px;box-shadow:none;border:1px solid #c5d5f2;touch-action:manipulation}
.bpSharedCell:disabled{opacity:1}.bpSharedCell:not(:disabled):active{outline:3px solid #fff}
#bpSharedPieces{display:flex;gap:6px;justify-content:center;align-items:stretch;margin:8px 0}
.bpSharedChoice{min-width:76px;min-height:75px;display:flex;flex-direction:column;gap:5px;align-items:center;justify-content:center;background:#fff;color:#314a87;border:2px solid #ccdcfa;box-shadow:0 3px 0 #b3c4e8;padding:6px;border-radius:11px}
.bpSharedChoice.chosen{border:3px solid #715ada;background:#ebe4ff}.bpSharedChoice:disabled{opacity:.55}.bpSharedChoice small{font-size:9px}
.bpSharedShape{display:grid;grid-auto-rows:14px;gap:2px}.bpSharedShape i{display:block;width:14px;height:14px;border-radius:3px}
.bpScore{background:#e4f6ef;padding:9px;border-radius:9px;font-weight:850;font-size:12px;margin:6px 0;overflow-wrap:anywhere}
.bpVersus{font-size:14px;text-align:center;font-weight:1000;color:#2e5cb3;padding:5px}
.bpTinyStatus{font-size:12px;text-align:center;color:#475f86;margin:6px 0;font-weight:800}
@media(max-height:650px){#bpSharedBoard{width:min(72vw,270px);height:min(72vw,270px)}.bpScreen{padding:9px}}
</style>

// v1.4.0 ACCOUNT + SERVER-AUTHORITATIVE SHARED BOARD
const accountModal=document.getElementById('bpAccountModal');
const accountStatus=document.getElementById('bpAccountStatus');
const accountSigned=document.getElementById('bpAccountSigned');
const accountLoginForm=document.getElementById('bpAccountLoginForm');
const SHARED_RESUME_KEY='blockpop_shared_reconnect_v1',ACCOUNT_SESSION_KEY='blockpop_account_auth_v1';
let accountSession=null,accountNickname='ゲスト',accountLastCloud='';
try{const raw=JSON.parse(localStorage.getItem(ACCOUNT_SESSION_KEY)||'null');if(raw?.accessToken&&raw?.refreshToken)accountSession=raw}catch{}
function accountMessage(msg){accountStatus.textContent=msg;}
function accountSaveSession(data){
 accountSession=data;try{if(data)localStorage.setItem(ACCOUNT_SESSION_KEY,JSON.stringify(data));else localStorage.removeItem(ACCOUNT_SESSION_KEY)}catch{}
 accountNickname=data?.nickname||'ゲスト';accountView();
}
function accountView(){
 const active=!!accountSession;
 accountLoginForm.hidden=active;accountSigned.hidden=!active;
 document.getElementById('bpAccountIdentity').textContent=active?'👤 '+accountNickname:'ゲスト';
 document.getElementById('bpAccountBtn').textContent=active?'👤 '+accountNickname.slice(0,6):'👤 アカウント';
}
async function accountApi(route,{body,auth=false,canRetry=true}={}){
 const ctrl=new AbortController(),id=setTimeout(()=>ctrl.abort(),60000);
 try{
  const res=await fetch(ONLINE_ORIGIN+'/api/account/'+route,{method:body?'POST':'GET',mode:'cors',cache:'no-store',signal:ctrl.signal,
   headers:{...(body?{'Content-Type':'application/json'}:{}),...(auth&&accountSession?{'Authorization':'Bearer '+accountSession.accessToken}:{})},...(body?{body:JSON.stringify(body)}:{})});
  let d;try{d=await res.json()}catch{throw Error('アカウントサーバーの応答が読めないよ')}
  if(res.status===401&&auth&&canRetry&&accountSession?.refreshToken){
   try{const refreshed=await accountApi('refresh',{body:{refreshToken:accountSession.refreshToken},canRetry:false});
    if(refreshed.session){accountSaveSession(refreshed.session);return accountApi(route,{body,auth,canRetry:false});}
   }catch(e){accountSaveSession(null);throw Error('ログインの期限が切れたよ。再ログインしてね');}
  }
  if(!res.ok)throw Error(d.error||'アカウントエラー HTTP '+res.status);
  return d;
 }catch(e){if(e?.name==='AbortError')throw Error('サーバーが応答しないよ。もう一度試してね');throw e;}
 finally{clearTimeout(id);}
}
function showAccount(){accountModal.classList.add('show');accountView();if(accountSession)accountLoadProfile();}
async function accountLoadProfile(){
 if(!accountSession)return;
 try{const d=await accountApi('me',{auth:true});accountNickname=d.user?.nickname||accountNickname;
  accountSession.nickname=accountNickname;accountSaveSession(accountSession);
  const save=await accountApi('backup',{auth:true});
  accountLastCloud=save.updatedAt||'';
  accountMessage(save.save?'☁️ クラウドバックアップあり：'+new Date(save.updatedAt).toLocaleString('ja-JP'):'☁️ クラウドにはまだバックアップがないよ');
 }catch(e){accountMessage('⚠️ '+e.message);}
}
document.getElementById('bpAccountBtn').addEventListener('click',showAccount);
document.getElementById('bpAccountClose').addEventListener('click',()=>accountModal.classList.remove('show'));
document.getElementById('bpAccountRegister').addEventListener('click',()=>accountDoLogin(true));
document.getElementById('bpAccountLogin').addEventListener('click',()=>accountDoLogin(false));
async function accountDoLogin(register){
 const email=document.getElementById('bpAccountEmail').value.trim();const pw=document.getElementById('bpAccountPassword').value;
 const nickname=document.getElementById('bpAccountNickname').value.trim()||'Player';
 if(!email.includes('@')||pw.length<8){accountMessage('メールアドレスと8文字以上のパスワードを入力してね');return;}
 accountMessage(register?'🔐 アカウント作成中…':'🔓 ログイン中…');
 try{const d=await accountApi(register?'register':'login',{body:{email,password:pw,...(register?{nickname}:{})}});
  document.getElementById('bpAccountPassword').value='';
  if(d.session){accountSaveSession(d.session);await accountLoadProfile();accountMessage('✅ '+(register?'アカウントを作成したよ！':'ログインできたよ！')+' ☁️ 保存する場合は「クラウドへ保存」を押してね');}
  else accountMessage('📨 '+(d.message||'確認メールのリンクを開いてからログインしてね'));
 }catch(e){accountMessage('⚠️ '+e.message);}
}
document.getElementById('bpAccountLogout').addEventListener('click',()=>{
 accountSaveSession(null);accountMessage('🚪 ログアウトしたよ。端末のセーブは残るよ。');
});
document.getElementById('bpCloudSave').addEventListener('click',()=>cloudSave(false));
async function cloudSave(silent){
 if(!accountSession)return;
 if(gameMode==='battle'){if(!silent)accountMessage('対戦中はバックアップを保存できないよ');return;}
 if(!silent)accountMessage('☁️ クラウドへ保存中…');
 try{
  const save=makeBackupObject();const result=await accountApi('backup',{auth:true,body:{save}});
  accountLastCloud=result.updatedAt;
  try{localStorage.setItem('blockpop_cloud_ready_'+accountSession.userId,'yes')}catch{}
  if(!silent)accountMessage('✅ クラウド保存成功：'+new Date(accountLastCloud).toLocaleString('ja-JP'));
 }catch(e){if(!silent)accountMessage('⚠️ '+e.message);}
}
document.getElementById('bpCloudRestore').addEventListener('click',async()=>{
 if(!accountSession)return;
 accountMessage('☁️ クラウドデータを確認中…');
 try{const data=await accountApi('backup',{auth:true});
  if(!data.save){accountMessage('📭 クラウドにバックアップがないよ');return;}
  if(!confirm('この端末のセーブデータを、クラウドの保存内容で置き換えるよ。続ける？')){
   accountMessage('復元を中止したよ');return;
  }
  importBackupObject(data.save);
  try{localStorage.setItem('blockpop_cloud_ready_'+accountSession.userId,'yes')}catch{}
  accountMessage('✅ クラウドから復元したよ！');
 }catch(e){accountMessage('⚠️ '+e.message);}
});
document.getElementById('bpCloudAuto').addEventListener('change',e=>{
 if(!accountSession){e.target.checked=false;accountMessage('先にログインしてね');return;}
 const ready=localStorage.getItem('blockpop_cloud_ready_'+accountSession.userId)==='yes';
 if(e.target.checked&&!ready){e.target.checked=false;accountMessage('先に「クラウドへ保存」か「復元」を1回してから自動同期をONにしてね');return;}
 try{localStorage.setItem('blockpop_cloud_auto_'+accountSession.userId,e.target.checked?'on':'off')}catch{}
 accountMessage(e.target.checked?'☁️ 自動バックアップON（約2分間隔）':'☁️ 自動バックアップOFF');
});
setInterval(()=>{
 if(!accountSession||document.visibilityState==='hidden'||gameMode==='battle')return;
 const uid=accountSession.userId;
 if(localStorage.getItem('blockpop_cloud_ready_'+uid)==='yes'&&localStorage.getItem('blockpop_cloud_auto_'+uid)==='on')cloudSave(true);
},120000);
// Shared board gameplay is completely separate from local single-player save.
const sharedModal=document.getElementById('bpSharedModal');
const sharedStatus=document.getElementById('bpSharedStatus');
const sharedBoard=document.getElementById('bpSharedBoard');
const sharedPieces=document.getElementById('bpSharedPieces');
const sharedRoomCode=document.getElementById('bpSharedCode');
let sharedWs=null,sharedState=null,sharedMySlot=-1,sharedSelected=0,sharedRotation=0,sharedRetry=0,sharedAutoRejoin=false,sharedManualStop=false;
const sharedCells=[];
for(let i=0;i<64;i++){
 const cell=document.createElement('button');cell.type='button';cell.className='bpSharedCell';cell.setAttribute('aria-label','行'+(Math.floor(i/8)+1)+' 列'+(i%8+1));
 cell.addEventListener('click',()=>sharedPlace(Math.floor(i/8),i%8));sharedBoard.appendChild(cell);sharedCells.push(cell);
}
function sharedMessage(t){sharedStatus.textContent=t;}
function getSharedResume(){try{return JSON.parse(localStorage.getItem(SHARED_RESUME_KEY)||'null')}catch{return null}}
function setSharedResume(v){try{if(v)localStorage.setItem(SHARED_RESUME_KEY,JSON.stringify(v));else localStorage.removeItem(SHARED_RESUME_KEY)}catch{}}
function sendShared(obj){if(sharedWs?.readyState===WebSocket.OPEN)sharedWs.send(JSON.stringify(obj));}
function sharedNick(){return (accountSession?.nickname||document.getElementById('bpGuestName').value.trim()||'ゲスト').slice(0,16)}
function showShared(){
 onlineModal.classList.remove('show');sharedModal.classList.add('show');sharedManualStop=false;
 const previous=getSharedResume();if(previous&&!sharedState){sharedMessage('🔄 前の共有対戦に再接続中…');sharedConnect({type:'shared_resume',code:previous.code,token:previous.token});}
}
function sharedConnect(command){
 if(sharedWs?.readyState===WebSocket.OPEN){if(command)sendShared(command);return;}
 if(sharedWs?.readyState===WebSocket.CONNECTING)return;
 sharedMessage('📡 共有盤面サーバーに接続中…');let ws;
 try{ws=new WebSocket(ONLINE_SOCKET);}catch{sharedMessage('⚠️ サーバーに接続できないよ');return;}
 sharedWs=ws;
 ws.onopen=()=>{if(sharedWs!==ws)return;sharedRetry=0;sharedMessage('✅ 接続したよ');if(command)sendShared(command);else{const saved=getSharedResume();if(saved)sendShared({type:'shared_resume',code:saved.code,token:saved.token});}};
 ws.onmessage=e=>{if(sharedWs!==ws)return;try{sharedReceive(JSON.parse(e.data))}catch{}};
 ws.onerror=()=>{if(sharedWs===ws)sharedMessage('⚠️ 通信が不安定だよ。接続を確認してね');};
 ws.onclose=()=>{
  if(sharedWs!==ws)return;sharedWs=null;
  if(sharedManualStop)return;
  const previous=getSharedResume();if(!previous){sharedMessage('📡 サーバーとの接続が切れたよ。もう一度ボタンを押してね');return;}
  sharedMessage('⚠️ 切断したよ。自動で再接続を試すね…');
  if(++sharedRetry<=10)setTimeout(()=>{if(!sharedManualStop&&sharedModal.classList.contains('show'))sharedConnect({type:'shared_resume',code:previous.code,token:previous.token})},4000);
 };
}
function sharedReceive(m){
 if(m.type==='shared_joined'){
  sharedMySlot=m.slot;setSharedResume({code:m.code,token:m.reconnectToken});sharedRoomCode.textContent='ルーム：'+m.code;
  sharedMessage('🔑 参加成功！コードを友だちに伝えてね');
 }else if(m.type==='shared_waiting'){
  sharedMessage(m.waiting?'🔎 ランダム対戦の相手を探しているよ…':'検索を中止したよ');
 }else if(m.type==='shared_state'){
  sharedState=m.state;sharedRoomCode.textContent='ルーム：'+m.state.code;
  sharedDraw();
 }else if(m.type==='shared_finished'){
  sharedState=m.state;sharedDraw();setSharedResume(null);
  const winner=m.winner;
  sharedMessage(winner===null?'🏁 引き分け！':winner===sharedMySlot?'🏆 あなたの勝ち！':'🎮 相手の勝ち！');
 }else if(m.type==='shared_error'){
  sharedMessage('⚠️ '+String(m.message||'エラー'));
  if(/無効|終了/.test(m.message||''))setSharedResume(null);
 }else if(m.type==='shared_left'){
  setSharedResume(null);sharedState=null;sharedMySlot=-1;sharedDraw();sharedMessage('🚪 部屋から退出したよ');
 }
}
function sharedRotated(shape,turn){
 let out=shape;for(let k=0;k<turn;k++)out=out[0].map((_,c)=>out.map(row=>row[c]).reverse());return out;
}
function sharedDraw(){
 const s=sharedState;
 const play=s?.status==='playing'&&s.turn===sharedMySlot;
 const names=s?.players||[];
 document.getElementById('bpSharedPlayers').textContent=names.filter(Boolean).map((p,i)=>(p.slot===sharedMySlot?'⭐ ':'')+p.name+' '+p.score+'点'+(p.connected?' 🟢':' ⚪')).join(' VS ')||'相手を待っています';
 document.getElementById('bpSharedTurn').textContent=!s?'部屋を作るか、対戦相手を探してね':s.status==='lobby'?'⏳ 友だちの参加を待っているよ':s.status==='finished'?'🏁 対戦終了':play?'🟢 あなたの番！ ブロックとマスを選ぼう':'🔵 相手の番。盤面が更新されるよ';
 for(let i=0;i<64;i++){
  const val=s?.board?.[i]||0,c=sharedCells[i];c.style.background=val?(COLORS[val-1]?.[1]||'#5879dd'):'#e5eeff';c.disabled=!play||!!val;
 }
 sharedPieces.replaceChildren();if(!s?.pieces)return;
 for(let index=0;index<s.pieces.length;index++){
  const p=s.pieces[index],btn=document.createElement('button');btn.type='button';btn.className='bpSharedChoice'+(sharedSelected===index?' chosen':'');
  btn.disabled=p.used||!play;
  const shape=sharedRotated(p.shape,sharedSelected===index?sharedRotation:0);
  const grid=document.createElement('span');grid.className='bpSharedShape';grid.style.gridTemplateColumns='repeat('+shape[0].length+',14px)';
  shape.forEach(row=>row.forEach(n=>{const c=document.createElement('i');c.style.background=n?(COLORS[p.color-1]?.[1]||'#486ff5'):'transparent';grid.appendChild(c)}));
  btn.appendChild(grid);const tag=document.createElement('small');tag.textContent=p.used?'使用済み':'ブロック '+(index+1);btn.appendChild(tag);
  btn.addEventListener('click',()=>{sharedSelected=index;sharedRotation=0;sharedDraw()});sharedPieces.appendChild(btn);
 }
 document.getElementById('bpSharedRotate').disabled=!play||!s?.pieces?.[sharedSelected]||s.pieces[sharedSelected].used;
}
function sharedPlace(row,col){
 if(!sharedState||sharedState.status!=='playing'||sharedState.turn!==sharedMySlot)return;
 const piece=sharedState.pieces[sharedSelected];if(!piece||piece.used)return;
 const shape=sharedRotated(piece.shape,sharedRotation);
 for(let r=0;r<shape.length;r++)for(let c=0;c<shape[r].length;c++)if(shape[r][c]&&(row+r>=8||col+c>=8||sharedState.board[(row+r)*8+col+c])){
  sharedMessage('そこには置けないよ。左上のマスを選んでね');return;
 }
 sendShared({type:'shared_move',piece:sharedSelected,row,col,rotation:sharedRotation,seq:sharedState.seq});
}
document.getElementById('bpSharedBtn').addEventListener('click',showShared);
document.getElementById('bpSharedFromOnline').addEventListener('click',showShared);
document.getElementById('bpSharedClose').addEventListener('click',()=>sharedModal.classList.remove('show'));
document.getElementById('bpSharedCreate').addEventListener('click',()=>{sharedSelected=0;sharedRotation=0;sharedConnect({type:'shared_create',name:sharedNick()});});
document.getElementById('bpSharedJoin').addEventListener('click',()=>{const code=document.getElementById('bpSharedJoinCode').value.trim().toUpperCase();sharedConnect({type:'shared_join',code,name:sharedNick()});});
document.getElementById('bpSharedQuick').addEventListener('click',()=>{sharedConnect({type:'shared_queue',name:sharedNick()});});
document.getElementById('bpSharedRotate').addEventListener('click',()=>{sharedRotation=(sharedRotation+1)%4;sharedDraw()});
document.getElementById('bpSharedLeave').addEventListener('click',()=>{
 sharedManualStop=true;sendShared({type:'shared_leave'});sendShared({type:'shared_cancel'});
 try{sharedWs?.close()}catch{}sharedWs=null;setSharedResume(null);sharedState=null;sharedMySlot=-1;sharedDraw();sharedMessage('🚪 退出したよ');
});
setInterval(()=>{if(!sharedState||sharedState.status!=='playing')return;
 const sec=Math.max(0,Math.ceil((sharedState.expiresAt-Date.now())/1000));
 document.getElementById('bpSharedTimer').textContent='残り '+Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0');
},1000);
accountView();sharedDraw();

